from __future__ import annotations

from html import escape

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse

from .esp_niche import require_esp_social_member

router = APIRouter()


@router.get("/command-center/social", response_class=HTMLResponse, include_in_schema=False)
def social_house(request: Request):
    member, esp_membership, profile = require_esp_social_member(request)
    definition = profile["catalog"]
    accent = definition["theme"]["accent"]
    secondary = definition["theme"]["secondary"]
    niche_title = definition["title"]
    niche_icon = definition["icon"]
    role = esp_membership.get("roles") or ("owner" if esp_membership.get("status") == "owner" else "member")
    training_cards = "".join(
        f"<li>{escape(item)}</li>" for item in definition.get("training", [])
    )

    html = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'><meta name='robots' content='noindex,nofollow'><meta name='theme-color' content='#05040b'><title>ESP Social Management</title><style>
:root{--bg:#03040a;--panel:#0d0f1b;--line:#ffffff1c;--gold:__ACCENT__;--violet:__SECONDARY__;--cyan:#5ce8ff;--green:#7ce0aa;--muted:#b7bbce;--text:#fff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 8% 0,var(--violet),transparent 29%),radial-gradient(circle at 94% 6%,var(--gold),transparent 23%),linear-gradient(#03040a,#070811 65%,#020309);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}.wrap{width:min(1450px,calc(100% - 28px));margin:auto}.nav{position:sticky;top:0;z-index:10;background:#05060bee;backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.navin{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{font-weight:950}.brand small{display:block;color:var(--gold);font-size:.64rem;text-transform:uppercase;letter-spacing:.08em}.navlinks,.actions{display:flex;gap:7px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#ffffff08;color:#fff;border-radius:12px;padding:9px 12px;font-weight:800;cursor:pointer}.btn.primary{border:0;background:linear-gradient(115deg,var(--gold),var(--violet));color:#130b18}.btn.small{font-size:.72rem;padding:6px 8px}.hero{padding:42px 0 22px}.eyebrow{color:var(--gold);font-size:.72rem;font-weight:950;letter-spacing:.17em;text-transform:uppercase}.hero h1{font-size:clamp(2.7rem,6vw,5.2rem);letter-spacing:-.055em;line-height:.93;margin:.14em 0 .2em}.hero h1 span{background:linear-gradient(95deg,#fff,var(--gold),var(--violet));background-clip:text;color:transparent}.lead{color:var(--muted);max-width:1020px;line-height:1.6}.statusline{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.chip{border:1px solid var(--line);border-radius:999px;padding:6px 9px;font-size:.72rem;color:#ddd}.chip.good{color:var(--green);border-color:#7ce0aa40}.private{border:1px solid var(--gold);background:#0008;border-radius:17px;padding:14px;margin:14px 0 20px}.layout{display:grid;grid-template-columns:270px 1fr;gap:14px;padding-bottom:60px}.sidebar,.panel{border:1px solid var(--line);background:linear-gradient(145deg,#101323e8,#080a14f0);border-radius:21px;padding:16px}.sidebar{height:max-content;position:sticky;top:88px}.sidebar h3{margin:3px 0 12px}.space{border:1px solid var(--line);border-radius:12px;padding:10px;margin:7px 0;background:#ffffff05;cursor:pointer}.space.active{border-color:var(--gold);background:#ffffff0b}.tabs{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:14px}.tab{border:1px solid var(--line);border-radius:999px;padding:7px 10px;background:#ffffff05;cursor:pointer;font-size:.8rem;font-weight:800;color:#fff}.tab.active{background:#ffffff12;border-color:var(--gold)}.field{width:100%;border:1px solid var(--line);background:#070913;color:#fff;border-radius:11px;padding:10px;outline:none}.field:focus{border-color:var(--gold)}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.metric,.card{border:1px solid var(--line);background:#ffffff05;border-radius:16px;padding:14px}.metric b{font-size:1.5rem;display:block}.metric small,.muted{color:var(--muted)}.board{display:grid;grid-template-columns:repeat(4,minmax(220px,1fr));gap:10px;overflow:auto}.column{border:1px solid var(--line);border-radius:16px;padding:10px;background:#070914;min-height:280px}.column h4{margin:4px 0 10px;text-transform:capitalize}.post{border:1px solid var(--line);border-radius:13px;padding:11px;background:#111427;margin:8px 0}.post strong{display:block}.post small{color:var(--muted)}.platforms{margin:7px 0}.platforms span{display:inline-block;border:1px solid var(--line);border-radius:999px;font-size:.64rem;padding:3px 6px;margin:2px}.forms{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px}.formbox{border:1px solid var(--line);border-radius:16px;padding:13px;background:#ffffff04}.stack{display:grid;gap:8px}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.empty{border:1px dashed #ffffff28;border-radius:14px;padding:20px;text-align:center;color:var(--muted)}.notice{display:none;border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin-bottom:12px}.notice.show{display:block}.notice.error{border-color:#ff8f9d50;color:#ffd6dc}.featuregrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.feature h4{margin:7px 0}.feature p{color:var(--muted);font-size:.86rem;line-height:1.5}.training ul{padding-left:20px;color:var(--muted);line-height:1.55}.footer{border-top:1px solid var(--line);padding:28px 0 42px;color:var(--muted);font-size:.85rem}@media(max-width:1050px){.layout{grid-template-columns:1fr}.sidebar{position:relative;top:auto}.grid,.featuregrid{grid-template-columns:repeat(2,1fr)}}@media(max-width:680px){.grid,.featuregrid,.forms,.row{grid-template-columns:1fr}.board{grid-template-columns:repeat(4,260px)}.navlinks .optional{display:none}}
</style></head><body>
<nav class='nav'><div class='wrap navin'><a class='brand' href='/command-center'>Elevate Souls Productions<small>Private Creator & Agent Hub · Social Growth Suite</small></a><div class='navlinks'><a class='btn optional' href='/command-center'>ESP Hub</a><a class='btn optional' href='/command-center/niche'>Change Niche</a><a class='btn' href='/dashboard'>Account</a></div></div></nav>
<main class='wrap'><section class='hero'><div class='eyebrow'>__NICHE_ICON__ __NICHE_TITLE__ · Aura Social Intelligence</div><h1>Plan. Train. Create. <span>Grow your community.</span></h1><p class='lead'>This is the private ESP social-management workspace for your selected niche. It is part of Elevate Souls Productions creator/agent training and operations, not part of the public Pulsar-Frequency House Creative Studio.</p><div class='statusline'><span class='chip good'>✓ ESP approved</span><span class='chip good'>✓ Niche: __NICHE_TITLE__</span><span class='chip good'>✓ Role: __ROLE__</span><span class='chip good'>✓ No other Creator Network declared</span><span class='chip'>Official publishing requires authorised platform connections</span></div></section>
<section class='private'><strong>ESP no-poaching boundary</strong><div class='muted'>This workspace is restricted to approved ESP members whose account is not represented by another Creator Network. If affiliation changes, social-management access is blocked at the server/API layer.</div></section><div id='notice' class='notice'></div>
<section class='layout'><aside class='sidebar'><div class='eyebrow'>Your niche training</div><div class='training'><ul>__TRAINING__</ul></div><hr style='border:0;border-top:1px solid var(--line);margin:16px 0'><div class='eyebrow'>Social Houses</div><h3>Accounts & campaigns</h3><div id='spaces'><div class='empty'>No Social Houses yet.</div></div><div class='stack' style='margin-top:12px'><input id='spaceName' class='field' placeholder='Creator / brand / campaign'><button class='btn primary' onclick='createSpace()'>Create Social House</button></div></aside>
<section class='panel'><div class='tabs'><button class='tab active' onclick="showTab('overview',this)">Overview</button><button class='tab' onclick="showTab('board',this)">Board</button><button class='tab' onclick="showTab('calendar',this)">Calendar</button><button class='tab' onclick="showTab('campaigns',this)">Campaigns</button><button class='tab' onclick="showTab('tasks',this)">Tasks</button><button class='tab' onclick="showTab('persona',this)">Aura Persona</button><button class='tab' onclick="showTab('features',this)">Feature Map</button></div><div id='content'><div class='empty'>Choose or create a Social House.</div></div></section></section></main>
<footer class='footer'><div class='wrap'><strong>Elevate Souls Productions</strong> · Private ESP Creator & Agent Social Management · Powered by Aura AI Systems</div></footer>
<script>
const BASE='/command-center/api/social';let spaces=[],house=null,activeTab='overview';const qs=id=>document.getElementById(id);
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function notice(m,e=false){const n=qs('notice');n.textContent=m;n.className='notice show'+(e?' error':'');clearTimeout(window._n);window._n=setTimeout(()=>n.className='notice',6500)}
async function api(p,o={}){const r=await fetch(BASE+p,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(o.headers||{})},...o});let b={};try{b=await r.json()}catch(e){}if(!r.ok)throw new Error(b.detail||`Request failed (${r.status})`);return b}
async function loadSpaces(){try{const d=await api('/spaces');spaces=d.spaces||[];renderSpaces();if(!house&&spaces.length)await loadHouse(spaces[0].id)}catch(e){notice(e.message,true)}}
function renderSpaces(){qs('spaces').innerHTML=spaces.length?spaces.map(s=>`<div class="space ${house?.id===s.id?'active':''}" onclick="loadHouse('${s.id}')"><strong>${esc(s.name)}</strong><div class="muted" style="font-size:.72rem">${esc(s.description||'ESP Social House')}</div></div>`).join(''):'<div class="empty">No Social Houses yet.</div>'}
async function createSpace(){const name=qs('spaceName').value.trim();if(!name)return notice('Enter a creator, brand or campaign name.',true);try{house=await api('/spaces',{method:'POST',body:JSON.stringify({name,description:'ESP niche-specific social workspace'})});qs('spaceName').value='';await loadSpaces();await loadHouse(house.id);notice('ESP Social House created.')}catch(e){notice(e.message,true)}}
async function loadHouse(id){try{house=await api(`/spaces/${encodeURIComponent(id)}`);renderSpaces();renderTab()}catch(e){notice(e.message,true)}}
function showTab(t,el){activeTab=t;document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));el.classList.add('active');renderTab()}
function renderTab(){if(!house){qs('content').innerHTML='<div class="empty">Choose or create a Social House.</div>';return}const fn={overview:renderOverview,board:renderBoard,calendar:renderCalendar,campaigns:renderCampaigns,tasks:renderTasks,persona:renderPersona,features:renderFeatures}[activeTab]||renderOverview;qs('content').innerHTML=fn()}
function renderOverview(){const scheduled=house.content.filter(x=>['scheduled','publishing'].includes(x.status)).length,published=house.content.filter(x=>x.status==='published').length,pending=house.content.filter(x=>x.status==='pending_approval').length;return `<div class="grid"><div class="metric"><b>${house.content.length}</b><small>Content items</small></div><div class="metric"><b>${scheduled}</b><small>Scheduled</small></div><div class="metric"><b>${pending}</b><small>Awaiting approval</small></div><div class="metric"><b>${published}</b><small>Published</small></div></div><div class="forms" style="margin-top:12px"><div class="formbox"><h3>Quick content idea</h3><div class="stack"><input id="postTitle" class="field" placeholder="Content title"><div class="row"><select id="postPlatform" class="field"><option>tiktok</option><option>instagram</option><option>youtube</option><option>facebook</option><option>linkedin</option><option>threads</option><option>x</option><option>pinterest</option></select><select id="postType" class="field"><option>video</option><option>photo</option><option>reel</option><option>post</option><option>short</option><option>story</option></select></div><textarea id="postCaption" class="field" placeholder="Caption or Aura draft"></textarea><label class="muted"><input id="approvalRequired" type="checkbox"> Require approval before publishing</label><button class="btn primary" onclick="addContent()">Add content</button></div></div><div class="formbox"><h3>Aura niche coach</h3><p class="muted">Aura should use your selected niche, audience, goals and ESP training priorities when planning content. This workspace remains operationally separate from the Creative Studio.</p><button class="btn" onclick="notice('Aura niche campaign generation is in the next integration stage.')">Plan niche campaign</button></div></div><div class="featuregrid"><div class="card feature"><div>🗓️</div><h4>Plan</h4><p>Board, calendar, campaigns, statuses, platform variants and unscheduled ideas.</p></div><div class="card feature"><div>✅</div><h4>Approve</h4><p>Approval-required content stays blocked from future auto-publishing until cleared.</p></div><div class="card feature"><div>🧠</div><h4>Train</h4><p>Aura combines ESP guidance with the user's niche, goals, audience and performance data.</p></div></div>`}
async function addContent(){const title=qs('postTitle').value.trim();if(!title)return notice('Enter a content title.',true);try{const d=await api(`/spaces/${house.id}/content`,{method:'POST',body:JSON.stringify({title,status:'idea',approval_required:qs('approvalRequired').checked,content_pillars:[],variants:[{platform:qs('postPlatform').value,content_type:qs('postType').value,caption:qs('postCaption').value.trim(),hashtags:[],media_refs:[],auto_publish:false}]})});house=d.house;renderTab();notice('Content added.')}catch(e){notice(e.message,true)}}
function postCard(p){return `<div class="post"><strong>${esc(p.title)}</strong><div class="platforms">${(p.variants||[]).map(v=>`<span>${esc(v.platform)}</span>`).join('')}</div><small>${p.approval_required?'Approval required':'Standard workflow'}</small></div>`}
function renderBoard(){const cols=['idea','in_production','pending_approval','approved'];return `<div class="board">${cols.map(s=>`<div class="column"><h4>${s.replaceAll('_',' ')}</h4>${house.content.filter(x=>x.status===s).map(postCard).join('')||'<div class="muted">No content</div>'}</div>`).join('')}</div>`}
function renderCalendar(){const scheduled=house.content.flatMap(p=>(p.variants||[]).filter(v=>v.scheduled_at).map(v=>({p,v}))).sort((a,b)=>String(a.v.scheduled_at).localeCompare(String(b.v.scheduled_at)));return `<h3>Content Calendar</h3><p class="muted">Platform-specific scheduled variants appear here. Calendar/month/week interfaces and official publishing adapters build on this data.</p>${scheduled.length?scheduled.map(x=>`<div class="post"><strong>${esc(x.p.title)}</strong><div>${esc(x.v.platform)} · ${esc(x.v.scheduled_at)}</div></div>`).join(''):'<div class="empty">Nothing scheduled yet.</div>'}`}
function renderCampaigns(){return `<div class="forms"><div class="formbox"><h3>Campaigns</h3>${house.projects.length?house.projects.map(p=>`<div class="post"><strong>${esc(p.name)}</strong><small>${esc(p.description||'')}</small></div>`).join(''):'<div class="empty">No campaigns yet.</div>'}</div><div class="formbox"><h3>Campaign system</h3><p class="muted">Campaigns group niche-specific content, tasks, notes, launches and reporting. Aura will be able to build these from ESP goals and authorised social performance data.</p></div></div>`}
function renderTasks(){return `<h3>Tasks & workflow</h3>${house.tasks.length?house.tasks.map(t=>`<div class="post"><strong>${esc(t.title)}</strong><small>${esc(t.status)} · ${esc(t.priority)}</small></div>`).join(''):'<div class="empty">No tasks yet. Task creation and assignments are available through the private ESP API foundation.</div>'}`}
function renderPersona(){const p=house.persona||{};return `<div class="formbox"><h3>Aura Social Persona</h3><p class="muted">The Social House persona supplements — never replaces — your ESP niche profile.</p><div class="grid"><div class="metric"><b>${esc(p.niche||'__NICHE_TITLE__')}</b><small>Niche</small></div><div class="metric"><b>${(p.content_pillars||[]).length}</b><small>Content pillars</small></div><div class="metric"><b>${(p.goals||[]).length}</b><small>Persona goals</small></div><div class="metric"><b>${(p.platform_priorities||[]).length}</b><small>Priority platforms</small></div></div></div>`}
function renderFeatures(){const f=[['📅','Calendar / Board / Table','Plan and manage content from idea through publication.'],['📲','Multi-platform variants','Platform-specific copy, media, timing and formats.'],['✅','Approvals','Internal review and future approval-link workflows.'],['📊','Analytics & reports','Official-platform data adapters, reporting and Aura insights.'],['💬','Social inbox','Future authorised comments/messages workspace where APIs permit.'],['🗂️','Media library','Reusable approved assets, folders and campaign media.'],['🧠','Aura niche intelligence','Training, content planning and recommendations based on the selected ESP niche.'],['🔁','Repurposing','Turn one approved idea into multiple platform-native variants.'],['👥','Agent workflow','Manage approved ESP creator workspaces without exposing tools publicly.']];return `<div class="featuregrid">${f.map(x=>`<div class="card feature"><div>${x[0]}</div><h4>${x[1]}</h4><p>${x[2]}</p></div>`).join('')}</div>`}
loadSpaces();
</script></body></html>"""
    return HTMLResponse(
        html.replace("__ACCENT__", accent)
        .replace("__SECONDARY__", secondary)
        .replace("__NICHE_TITLE__", escape(niche_title))
        .replace("__NICHE_ICON__", escape(niche_icon))
        .replace("__ROLE__", escape(str(role).title()))
        .replace("__TRAINING__", training_cards)
    )
